a=[json.loads(l) for l in open(H)]; b=[json.loads(l) for l in open('/tmp/claude-1000/dsg-audit/rerun_holdout_runs.jsonl')]
same_state=sum(x['result']['y_end']==y['result']['y_end'] for x,y in zip(a,b))
