// accepted-step time grid so that step-ratio statistics can be derived. No timing.
fn main() {
    for s in specs() {
        for tol in [1e-4, 1e-5, 1e-6, 1e-7, 1e-8] {
            let p = problem(&s);
            let allowed = CapabilitySet {
                explicit_jacobian: true,
                dense_matrix: true,
                newton: true,
                ..CapabilitySet::NONE
            };
            let o = PeerSolveOptions {
                rtol: tol,
                atol: tol * 1e-2,
                h0_rule_h_max: s.t_end / 100.0,
                threads: 1,
                ..PeerSolveOptions::default()
            };
            let sol = PeerOde::solve(&p, (0.0, s.t_end), &s.y0, &o, allowed).expect("admitted");
            let opts = Options {
                rtol: tol,
                atol: Atol::Scalar(tol * 1e-2),
                ..Options::default()
            };
            let r = Rodas5p::solve(&p, (0.0, s.t_end), &s.y0, &opts).expect("rodas5p");
            println!(
                "{}",
                json!({"problem": s.name, "tol": tol, "h0": sol.h0, "success": sol.success,
                       "accepted": sol.step_work.accepted_steps, "rejected": sol.step_work.rejected_steps,
                       "y_end": sol.y.last(), "t": sol.t,
                       "rodas5p_accepted": r.stats.accepted_steps, "rodas5p_rejected": r.stats.rejected_steps,
                       "rodas5p_y_end": r.final_state()})
            );
        }
    }
}
